class Solution:
    def findMaximumElegance(self, items: List[List[int]], k: int) -> int:
        items.sort(key=lambda it: -it[0])
        seen = set(); dup = []; total = 0
        for p, c in items[:k]:
            total += p
            if c in seen: dup.append(p)
            else: seen.add(c)
        d = len(seen)
        ans = total + d * d
        best = {}
        for p, c in items[k:]:
            if c not in best: best[c] = p
        cand = sorted(best.values(), reverse=True)
        dup.sort()
        i = 0
        while i < len(cand) and dup and cand[i] - dup[-1] + 2 * d + 1 > 0:
            total += cand[i] - dup.pop()
            d += 1
            ans = max(ans, total + d * d)
            i += 1
        return ans

