class Solution {
public:
    long long findMaximumElegance(vector<vector<int>>& items, int k) {
        sort(items.begin(), items.end(), [](auto& a, auto& b){ return a[0] > b[0]; });
        unordered_set<int> seen; vector<long long> dup; long long total = 0;
        for (int i = 0; i < k; i++) {
            total += items[i][0];
            if (!seen.insert(items[i][1]).second) dup.push_back(items[i][0]);
        }
        int d = seen.size();
        long long ans = total + (long long)d * d;
        unordered_map<int, long long> best;
        for (int i = k; i < (int)items.size(); i++)
            if (!best.count(items[i][1])) best[items[i][1]] = items[i][0];
        vector<long long> cand;
        for (auto& [c, p] : best) cand.push_back(p);
        sort(cand.rbegin(), cand.rend());
        sort(dup.begin(), dup.end());
        int i = 0;
        while (i < (int)cand.size() && !dup.empty() &&
               cand[i] - dup.back() + 2LL * d + 1 > 0) {
            total += cand[i] - dup.back(); dup.pop_back(); d++;
            ans = max(ans, total + (long long)d * d);
            i++;
        }
        return ans;
    }
};

