class Solution {
    public long findMaximumElegance(int[][] items, int k) {
        java.util.Arrays.sort(items, (a, b) -> b[0] - a[0]);
        Set<Integer> seen = new HashSet<>();
        List<Long> dup = new ArrayList<>(); long total = 0;
        for (int i = 0; i < k; i++) {
            total += items[i][0];
            if (!seen.add(items[i][1])) dup.add((long) items[i][0]);
        }
        int d = seen.size();
        long ans = total + (long) d * d;
        Map<Integer, Long> best = new HashMap<>();
        for (int i = k; i < items.length; i++)
            best.putIfAbsent(items[i][1], (long) items[i][0]);
        List<Long> cand = new ArrayList<>(best.values());
        cand.sort(java.util.Collections.reverseOrder());
        java.util.Collections.sort(dup);
        int i = 0;
        while (i < cand.size() && !dup.isEmpty() &&
               cand.get(i) - dup.get(dup.size() - 1) + 2L * d + 1 > 0) {
            total += cand.get(i) - dup.remove(dup.size() - 1);
            d++;
            ans = Math.max(ans, total + (long) d * d);
            i++;
        }
        return ans;
    }
}

