var findMaximumElegance = function(items, k) {
    items.sort((a, b) => b[0] - a[0]);
    const seen = new Set(); const dup = []; let total = 0;
    for (let i = 0; i < k; i++) {
        total += items[i][0];
        if (seen.has(items[i][1])) dup.push(items[i][0]);
        else seen.add(items[i][1]);
    }
    let d = seen.size;
    let ans = total + d * d;
    const best = new Map();
    for (let i = k; i < items.length; i++)
        if (!best.has(items[i][1])) best.set(items[i][1], items[i][0]);
    const cand = [...best.values()].sort((a, b) => b - a);
    dup.sort((a, b) => a - b);
    let i = 0;
    while (i < cand.length && dup.length && cand[i] - dup[dup.length - 1] + 2 * d + 1 > 0) {
        total += cand[i] - dup.pop();
        d++;
        ans = Math.max(ans, total + d * d);
        i++;
    }
    return ans;
};
